 @Transactional public Map<String,Object> prepararAmpliacion(long contrato,UUID u)throws IOException{long autor=gestionar(u);var f=detalle(contrato,u);var c=(Map<?,?>)f.get("contrato");if(!Set.of("BORRADOR","APROBADO","ACTIVO").contains(c.get("estado")))throw invalido("El contrato ya no admite trabajo nuevo");Map<String,Object>d=new LinkedHashMap<>();c.forEach((k,v)->d.put(k.toString(),v));Map<String,Object>cfg=(Map<String,Object>)f.get("configuracion");d.putAll(cfg);d.put("desde",c.get("desde").toString());d.put("hasta",c.get("hasta").toString());d.put("ampliar_contrato_id",contrato);d.put("piezas",List.of());d.put("referencias",List.of());d.put("documentos",List.of());d.put("prestaciones",alcance.listar(contrato));d.putIfAbsent("objetivo",Objects.toString(c.get("alcance"),"Continuación del servicio"));d.putIfAbsent("analisis_desde",c.get("desde").toString());d.putIfAbsent("analisis_hasta",c.get("hasta").toString());d.putIfAbsent("indicadores",List.of("IMPRESIONES","CLICS","CTR","CPC"));UUID id=UUID.randomUUID();guardarAlta(id,Map.of("datos",d,"version",0),u);return Map.of("id",id);}
 private void usuario(long id){if(jdbc.queryForObject("select count(*) from public.usuario where id_usuario=? and estado='ACTIVO'",Integer.class,id)!=1)throw invalido("Responsable inexistente o inactivo");}
 @Transactional public Map<String,Object> sincronizar(long contrato,long ad,Map<String,Object>d,UUID u){gestionar(u);var c=detalle(contrato,u);var acuerdo=(Map<?,?>)c.get("contrato");if(!Set.of("ACTIVO","APROBADO").contains(acuerdo.get("estado")))throw invalido("El contrato no está operativo");alcance.exigir(contrato,"ANALISIS");if(jdbc.queryForObject("select count(*) from public.crm_anuncio a where a.id=? and (a.contrato_id=? or exists(select 1 from public.crm_contrato_anuncio v where v.contrato_id=? and v.anuncio_id=a.id))",Integer.class,ad,contrato,contrato)!=1)error404();LocalDate desde=fecha(d,"desde"),hasta=fecha(d,"hasta");CrmPublicidadDemoServicio.periodo(desde,hasta);if(desde.isBefore(LocalDate.parse(acuerdo.get("desde").toString()))||hasta.isAfter(LocalDate.parse(acuerdo.get("hasta").toString())))throw invalido("Consulta un periodo dentro de la vigencia del contrato");Set<LocalDate> completos=new HashSet<>(jdbc.queryForList("select fecha from public.crm_anuncio_metrica where anuncio_id=? and fecha between ? and ? group by fecha having count(*)=9",LocalDate.class,ad,desde,hasta));var dias=desde.datesUntil(hasta.plusDays(1)).filter(f->!completos.contains(f)).toList();if(dias.isEmpty())return Map.of("filasNuevas",0);boolean organica=agencia.organico(ad);var filas=mockaroo.generar(dias);int n=0;for(var f:filas)n+=jdbc.update("insert into public.crm_anuncio_metrica values(?,?,?,?,?,?,?,?) on conflict do nothing",ad,f.fecha(),f.pais(),f.impresiones(),f.clics(),f.conversiones(),organica?BigDecimal.ZERO:f.inversion(),f.ingresos());evento(contrato,"ASOCIAR_MOCKAROO_ANUNCIO_"+ad,gestionar(u));return Map.of("filasNuevas",n);}
 @Transactional public void contenido(long contrato,long contenido,Map<String,Object>d,UUID u){gestionar(u);var filas=jdbc.queryForList("select c.* from public.crm_contenido c join public.crm_acuerdo_campana v on v.campana_id=c.campana_id where c.id=? and v.contrato_id=?",contenido,contrato);if(filas.isEmpty())error404();var pieza=filas.getFirst();pieza.put("estado",opcion(d,"estado","EN_REVISION","APROBADO","RECHAZADO","BORRADOR"));pieza.put("version",entero(d,"version",0,Integer.MAX_VALUE));operaciones.guardar("contenido",contenido,pieza,u);evento(contrato,"CONTENIDO_"+pieza.get("estado"),gestionar(u));}
 private long gestionar(UUID u){return acceso.exigir(u,"cuentas",true);}private void leer(UUID u){acceso.exigir(u,"atribucion",false);}
 private Map<String,Object> error404(){throw new ExcepcionApi(HttpStatus.NOT_FOUND,"CRM_CONTRATO_NO_EXISTE","Contrato o borrador no disponible");}
 private Map<String,Object> alta(UUID id,UUID u,boolean bloqueo){long autor=gestionar(u);var filas=jdbc.queryForList("select * from public.crm_alta_contrato where id=? and autor_id=?"+(bloqueo?" for update":""),id,autor);return filas.isEmpty()?error404():filas.getFirst();}
 private Map<String,Object> mapa(Object dato){try{return json.readValue(dato.toString(),new TypeReference<Map<String,Object>>(){});}catch(Exception e){throw invalido("Configuración del contrato inválida");}}
 public List<Map<String,Object>> borradores(UUID u){long autor=gestionar(u);return jdbc.queryForList("select id,datos->>'nombre' nombre,datos->>'servicio' servicio,version,updated_at from public.crm_alta_contrato where autor_id=? and contrato_id is null order by updated_at desc limit 100",autor);}
 public Map<String,Object> detalleAlta(UUID id,UUID u){var a=alta(id,u,false);return Map.of("id",id,"datos",mapa(a.get("datos")),"version",a.get("version"),"archivos",jdbc.queryForList("select id,nombre,mime,octet_length(contenido) bytes from public.crm_alta_archivo where alta_id=? order by created_at",id));}
 @Transactional public Map<String,Object> guardarAlta(UUID id,Map<String,Object>d,UUID u)throws IOException{
  long autor=gestionar(u);var datos=d.get("datos");if(!(datos instanceof Map<?,?>))throw invalido("Datos de borrador inválidos");String texto=json.writeValueAsString(datos);if(texto.length()>180000)throw invalido("El borrador excede el tamaño permitido");
  jdbc.update("insert into public.crm_alta_contrato(id,autor_id) values(?,?) on conflict do nothing",id,autor);var a=alta(id,u,true);if(a.get("contrato_id")!=null)throw invalido("El alta ya fue confirmada. Abre su ficha para continuar");
  if(jdbc.update("update public.crm_alta_contrato set datos=?::jsonb,version=version+1,updated_at=now() where id=? and version=?",texto,id,entero(d,"version",0,Integer.MAX_VALUE))==0)throw conflicto();return detalleAlta(id,u);
 }
 @Transactional public Map<String,Object> subir(UUID alta,UUID clave,MultipartFile archivo,UUID u)throws IOException{
  var a=alta(alta,u,true);if(a.get("contrato_id")!=null)throw invalido("El alta ya fue confirmada");if(archivo.isEmpty()||archivo.getSize()>20971520)throw invalido("Archivo vacío o mayor de 20 MB");byte[] bytes=archivo.getBytes();String mime;
  if(bytes.length>5&&new String(bytes,0,5,java.nio.charset.StandardCharsets.US_ASCII).equals("%PDF-"))mime="application/pdf";else mime=CrmEntregaServicio.tipo(bytes);
  String nombre=Objects.toString(archivo.getOriginalFilename(),"archivo").replaceAll("[\\\\/\\p{Cntrl}]","_");if(nombre.length()>160)nombre=nombre.substring(nombre.length()-160);
  var previo=jdbc.queryForList("select alta_id,nombre,contenido from public.crm_alta_archivo where id=?",clave);if(!previo.isEmpty()){var f=previo.getFirst();if(!alta.equals(f.get("alta_id"))||!Arrays.equals(bytes,(byte[])f.get("contenido")))throw conflicto();return Map.of("id",clave,"nombre",f.get("nombre"),"mime",mime);}
  if(jdbc.queryForObject("select count(*)>=30 or coalesce(sum(octet_length(contenido)),0)+?>104857600 from public.crm_alta_archivo where alta_id=?",Boolean.class,bytes.length,alta))throw invalido("El borrador admite hasta 30 archivos y 100 MB en total");
  jdbc.update("insert into public.crm_alta_archivo values(?,?,?,?,?,now())",clave,alta,nombre,mime,bytes);return Map.of("id",clave,"nombre",nombre,"mime",mime);
 }
 public Map<String,Object> archivo(UUID id,UUID u){leer(u);var filas=jdbc.queryForList("select f.*,a.autor_id,a.contrato_id from public.crm_alta_archivo f join public.crm_alta_contrato a on a.id=f.alta_id where f.id=?",id);if(filas.isEmpty())return error404();var f=filas.getFirst();if(f.get("contrato_id")==null && ((Number)f.get("autor_id")).longValue()!=gestionar(u))return error404();return f;}
 private List<Map<String,Object>> lista(Map<String,Object>d,String k){Object valor=d.get(k);if(valor==null)return List.of();if(!(valor instanceof List<?>l)||l.size()>60)throw invalido("Revisa la lista "+k);List<Map<String,Object>>r=new ArrayList<>();for(Object x:l){if(!(x instanceof Map<?,?>m))throw invalido("Registro inválido en "+k);Map<String,Object>v=new LinkedHashMap<>();m.forEach((a,b)->v.put(a.toString(),b));r.add(v);}return r;}
 private List<Map<String,Object>> canales(Map<String,Object>d){return lista(d,"canales");}
 private Map<String,Object> creativo(UUID alta,String id){try{var f=jdbc.queryForList("select * from public.crm_alta_archivo where id=? and alta_id=?",UUID.fromString(id),alta);if(f.isEmpty())throw invalido("El archivo no pertenece al borrador");return f.getFirst();}catch(IllegalArgumentException e){throw invalido("Archivo inválido");}}
 private String plataforma(Map<String,Object>d){return opcion(d,"plataforma","FACEBOOK","INSTAGRAM","TIKTOK","YOUTUBE","GOOGLE","OTRO");}
 public List<Map<String,Object>> buscar(long empresa,String plataforma,String referencia,UUID u){leer(u);if(!Set.of("FACEBOOK","INSTAGRAM","TIKTOK","YOUTUBE","GOOGLE","OTRO").contains(plataforma))throw invalido("Plataforma inválida");return jdbc.queryForList("select a.id,a.codigo,a.referencia_externa,a.nombre,a.formato,p.id cuenta_id,p.nombre cuenta,p.codigo cuenta_codigo,p.moneda,min(m.fecha) desde,max(m.fecha) hasta,count(m.fecha) filas from public.crm_anuncio a join public.crm_cuenta_publicitaria p on p.id=a.cuenta_id left join public.crm_anuncio_metrica m on m.anuncio_id=a.id where p.empresa_id=? and p.plataforma=? and (a.codigo=? or a.referencia_externa=?) group by a.id,p.id order by a.id limit 20",empresa,plataforma,referencia,referencia);}
 void resolverAudiencias(Map<String,Object>d,UUID u){
  List<Map<String,Object>> disponibles=null;
  var piezas=lista(d,"piezas");
  for(var pieza:piezas){var plan=canales(pieza);for(var canal:plan){
   if(vacio(canal.get("audiencia_id"))){
    if("PAGADA".equals(canal.get("modalidad"))&&canal.containsKey("audiencia_id"))throw invalido("Selecciona una audiencia registrada para "+canal.get("plataforma"));
    continue;
   }
   long id=numero(canal,"audiencia_id");
   if(disponibles==null)disponibles=administrador.listar("audiencias",u);
   var audiencia=disponibles.stream().filter(a->((Number)a.get("idSegmento")).longValue()==id&&"ACTIVO".equals(a.get("estado"))).findFirst().orElseThrow(()->invalido("La audiencia seleccionada ya no existe o está inactiva"));
   canal.put("audiencia",audiencia.get("nombre"));
   if(vacio(canal.get("cobertura")))canal.put("cobertura",Objects.toString(audiencia.get("ubicacionGeografica"),""));
  }pieza.put("canales",plan);}
  d.put("piezas",piezas);
 }
 private void validar(Map<String,Object>d,UUID alta){
  String servicio=opcion(d,"servicio","DIFUSION","ANALISIS","INTEGRAL");texto(d,"objetivo",2000,true);var piezas=lista(d,"piezas");var refs=lista(d,"referencias");LocalDate desde=fecha(d,"desde"),hasta=fecha(d,"hasta");boolean ampliar=!vacio(d.get("ampliar_contrato_id"));if(ampliar&&piezas.isEmpty()&&refs.isEmpty())throw invalido("Agrega al menos una pieza o referencia");
  int limiteAnalisis=lista(d,"prestaciones").stream().filter(p->"ANALISIS".equals(p.get("prestacion"))).mapToInt(p->entero(p,"cantidad",1,10000)).sum();if(!servicio.equals("DIFUSION")&&refs.size()>limiteAnalisis)throw invalido("Las referencias superan la cantidad de anuncios de análisis contratada");
  if(servicio.equals("ANALISIS")&&!piezas.isEmpty())throw invalido("Solo análisis no incluye piezas para difundir");
  if(!servicio.equals("ANALISIS")&&(!ampliar||!piezas.isEmpty())){
   if(piezas.isEmpty())throw invalido("Agrega al menos un material o producción pendiente");String modalidad=opcion(d,"modalidad","ORGANICA","PAGADA","MIXTA");BigDecimal plan=BigDecimal.ZERO;
   for(var p:piezas){texto(p,"titulo",160,true);texto(p,"descripcion",4000,true);String formato=opcion(p,"formato","VIDEO","IMAGEN","CARRUSEL","TEXTO");String fuente=opcion(p,"fuente","CLIENTE","AGENCIA");
    boolean pendiente=Boolean.TRUE.equals(p.get("pendiente"));if(pendiente){if(!fuente.equals("AGENCIA")||lista(d,"prestaciones").stream().noneMatch(x->"PRODUCCION".equals(x.get("prestacion"))))throw invalido("Producción pendiente requiere esa prestación");LocalDate entrega=fecha(p,"entrega");if(entrega.isBefore(desde)||entrega.isAfter(hasta))throw invalido("La entrega debe estar dentro de la vigencia");usuario(numero(p,"responsable_id"));}
    else if(!formato.equals("TEXTO")){List<Map<String,Object>> archivos=lista(p,"archivos");if(archivos.isEmpty())throw invalido("Carga el material de "+p.get("titulo"));for(var f:archivos){var a=creativo(alta,Objects.toString(f.get("id"),""));boolean video=a.get("mime").toString().startsWith("video/");if(formato.equals("VIDEO")!=video||a.get("mime").equals("application/pdf"))throw invalido("El formato del archivo no coincide con la pieza");}}
    if(canales(p).isEmpty())throw invalido("Selecciona canales para cada pieza");Set<String>unicos=new HashSet<>();for(var canal:canales(p)){if(!unicos.add(plataforma(canal)))throw invalido("Canal duplicado en una pieza");OffsetDateTime f=instante(canal,"programado_en");if(f.toLocalDate().isBefore(desde)||f.toLocalDate().isAfter(hasta))throw invalido("La publicación debe estar dentro de la vigencia");texto(canal,"objetivo",300,true);usuario(numero(canal,"responsable_id"));String tipo=opcion(canal,"modalidad","ORGANICA","PAGADA");if(modalidad.equals("ORGANICA")&&!tipo.equals("ORGANICA")||modalidad.equals("PAGADA")&&!tipo.equals("PAGADA"))throw invalido("La modalidad de cada canal debe coincidir con el plan");BigDecimal presupuesto=decimal(canal,"presupuesto");if(tipo.equals("PAGADA")){if(presupuesto.signum()<=0)throw invalido("Cada canal pagado necesita presupuesto");texto(canal,"audiencia",2000,true);texto(canal,"cobertura",1000,true);}else if(presupuesto.signum()>0)throw invalido("La publicación orgánica no lleva pauta");plan=plan.add(presupuesto);}
   }
   if(plan.compareTo(decimal(d,"presupuesto"))>0)throw invalido("La distribución por canales supera el presupuesto autorizado");
  }
  if(!servicio.equals("DIFUSION")&&(!ampliar||!refs.isEmpty())){
   if(refs.isEmpty())throw invalido("Agrega una referencia para el análisis");fecha(d,"analisis_desde");fecha(d,"analisis_hasta");if(fecha(d,"analisis_hasta").isBefore(fecha(d,"analisis_desde")))throw invalido("Periodo de análisis inválido");texto(d,"frecuencia",80,true);
   Set<String>unicos=new HashSet<>();for(var ref:refs){String plataforma=plataforma(ref);texto(ref,"nombre",160,true);String codigo=texto(ref,"referencia",160,true);if(!unicos.add(plataforma+"/"+codigo))throw invalido("Referencia repetida");texto(ref,"cuenta_nombre",160,true);texto(ref,"cuenta_codigo",80,true);}
  }
  for(var f:lista(d,"documentos"))if(!creativo(alta,f.get("id").toString()).get("mime").equals("application/pdf"))throw invalido("El documento contractual debe ser PDF");
 }
 private long cuenta(long empresa,String plataforma,String codigo,String nombre,String moneda){
  var f=jdbc.queryForList("select * from public.crm_cuenta_publicitaria where codigo=?",codigo);if(!f.isEmpty()){var c=f.getFirst();if(((Number)c.get("empresa_id")).longValue()!=empresa||!plataforma.equals(c.get("plataforma"))||!moneda.equals(c.get("moneda")))throw invalido("La cuenta pertenece a otra empresa/plataforma o moneda");return ((Number)c.get("id")).longValue();}
  return jdbc.queryForObject("insert into public.crm_cuenta_publicitaria(empresa_id,nombre,codigo,plataforma,moneda) values(?,?,?,?,?) returning id",Long.class,empresa,nombre,codigo,plataforma,moneda);
 }
 @Transactional public Map<String,Object> confirmar(UUID id,int version,UUID u)throws IOException{
  var alta=alta(id,u,true);if(alta.get("contrato_id")!=null)return Map.of("id",alta.get("contrato_id"));if(((Number)alta.get("version")).intValue()!=version)throw conflicto();var d=mapa(alta.get("datos"));boolean ampliar=!vacio(d.get("ampliar_contrato_id"));Map<String,Object>anterior=new LinkedHashMap<>();long contratoPrevio=0;if(ampliar){contratoPrevio=numero(d,"ampliar_contrato_id");jdbc.queryForList("select id from public.crm_acuerdo where id=? for update",contratoPrevio);var ficha=detalle(contratoPrevio,u);var c=(Map<?,?>)ficha.get("contrato");if(!Set.of("BORRADOR","APROBADO","ACTIVO").contains(c.get("estado")))throw invalido("El contrato no admite trabajo nuevo");for(String k:List.of("empresa_id","servicio","nombre","desde","hasta","responsable_id","moneda","honorarios","produccion","presupuesto","modalidad","alcance","condiciones","frecuencia"))d.put(k,c.get(k));d.put("desde",c.get("desde").toString());d.put("hasta",c.get("hasta").toString());d.put("prestaciones",alcance.listar(contratoPrevio));((Map<?,?>)ficha.get("configuracion")).forEach((k,v)->anterior.put(k.toString(),v));}resolverAudiencias(d,u);validar(d,id);if(ampliar){BigDecimal plan=BigDecimal.ZERO;for(var bloque:List.of(anterior,d))for(var p:lista(bloque,"piezas"))for(var canal:canales(p))plan=plan.add(decimal(canal,"presupuesto"));if(plan.compareTo(decimal(d,"presupuesto"))>0)throw invalido("La nueva planificación supera el presupuesto disponible");int cantidad=lista(anterior,"referencias").size()+lista(d,"referencias").size();int max=alcance.listar(contratoPrevio).stream().filter(p->"ANALISIS".equals(p.get("prestacion"))).mapToInt(p->((Number)p.get("cantidad")).intValue()).sum();if(cantidad>max)throw invalido("Las referencias superan el alcance contratado");}long autor=gestionar(u),empresa=numero(d,"empresa_id");String servicio=d.get("servicio").toString();
  Set<String> plataformas=new LinkedHashSet<>();for(var p:lista(d,"piezas"))canales(p).forEach(c->plataformas.add(plataforma(c)));lista(d,"referencias").forEach(r->plataformas.add(plataforma(r)));d.put("plataformas",String.join(",",plataformas));if(servicio.equals("ANALISIS")){d.put("modalidad","ORGANICA");d.put("presupuesto",0);d.put("produccion",0);}d.putIfAbsent("condiciones","");
  jdbc.queryForList("select id from public.crm_cuenta where id=? for update",empresa);long contrato=ampliar?contratoPrevio:((Number)agencia.guardar("contratos",null,d,u).get("id")).longValue();long cliente=jdbc.queryForObject("select cliente_id from public.crm_cuenta where id=?",Long.class,empresa);
  var canales=jdbc.queryForList("select id_canal from public.canal_difusion where estado='ACTIVO' order by id_canal limit 1");if(canales.isEmpty())throw invalido("Prepara el catálogo de canales de difusión antes de confirmar");
  var existentesCampana=jdbc.queryForList("select campana_id from public.crm_acuerdo_campana where contrato_id=? order by campana_id limit 1",contrato);long campana=!existentesCampana.isEmpty()?((Number)existentesCampana.getFirst().get("campana_id")).longValue():jdbc.queryForObject("insert into public.campana(nombre,id_cliente,id_canal,objetivo,presupuesto_asignado,fecha_inicio,fecha_fin,estado,id_usuario_creador) values(?,?,?,?,?,?,?,'PLANIFICADA',?) returning id_campana",Long.class,d.get("nombre"),cliente,canales.getFirst().get("id_canal"),d.get("objetivo"),decimal(d,"presupuesto"),fecha(d,"desde"),fecha(d,"hasta"),autor);jdbc.update("insert into public.crm_acuerdo_campana values(?,?) on conflict do nothing",contrato,campana);
  int publicacion=jdbc.queryForObject("select count(*) from public.crm_anuncio where contrato_id=?",Integer.class,contrato);
  for(var pieza:lista(d,"piezas")){
   long contenido=jdbc.queryForObject("insert into public.crm_contenido(nombre,campana_id,responsable_id,estado,texto) values(?,?,?,'BORRADOR',?) returning id",Long.class,pieza.get("titulo"),campana,autor,pieza.get("descripcion"));List<Long>anuncios=new ArrayList<>();
   for(var canal:canales(pieza)){if(!vacio(canal.get("audiencia_id")))administrador.vincularAudiencia(campana,numero(canal,"audiencia_id"),u);alcance.reservarAnuncio(contrato,false);String plataforma=plataforma(canal);long cuenta=cuenta(empresa,plataforma,"LOCAL-"+empresa+"-"+plataforma,"Cuenta de difusión "+plataforma,d.get("moneda").toString());OffsetDateTime fecha=instante(canal,"programado_en");String formato=pieza.get("formato").equals("CARRUSEL")?"IMAGEN":pieza.get("formato").toString();long ad=jdbc.queryForObject("insert into public.crm_anuncio(contrato_id,cuenta_id,campana_id,codigo,nombre,formato,contenido_id,fecha,programado_en,requiere_aprobacion_cliente) values(?,?,?,?,?,?,?,?,?,?) returning id",Long.class,contrato,cuenta,campana,"CTR-"+contrato+"-AD-"+(++publicacion),pieza.get("titulo")+" · "+plataforma,formato,contenido,fecha.toLocalDate(),fecha,Boolean.TRUE.equals(pieza.get("requiere_aprobacion")));anuncios.add(ad);jdbc.update("insert into public.crm_contrato_anuncio values(?,?,'CREADO')",contrato,ad);canal.put("anuncio_id",ad);
    for(var archivo:lista(pieza,"archivos")){var f=creativo(id,archivo.get("id").toString());jdbc.update("insert into public.crm_media_anuncio(anuncio_id,nombre,mime,contenido,autor_id) values(?,?,?,?,?)",ad,f.get("nombre"),f.get("mime"),f.get("contenido"),autor);}
   }pieza.put("anuncios",anuncios);pieza.put("contenido_id",contenido);
  }
  for(var ref:lista(d,"referencias")){
   String plataforma=plataforma(ref),codigo=texto(ref,"referencia",160,true);var existentes=buscar(empresa,plataforma,codigo,u);long ad;
   if(!existentes.isEmpty()){var x=existentes.getFirst();if(!d.get("moneda").equals(x.get("moneda")))throw invalido("La moneda del anuncio no coincide con el contrato");ad=((Number)x.get("id")).longValue();}
   else{long cuenta=cuenta(empresa,plataforma,texto(ref,"cuenta_codigo",80,true),texto(ref,"cuenta_nombre",160,true),d.get("moneda").toString());ad=jdbc.queryForObject("insert into public.crm_anuncio(contrato_id,cuenta_id,campana_id,codigo,nombre,formato,fecha,estado,referencia_externa) values(?,?,?,?,?,'TEXTO',?,'EXTERNO_SIMULADO',?) returning id",Long.class,contrato,cuenta,campana,"REF-"+UUID.randomUUID(),ref.get("nombre"),fecha(d,"analisis_desde"),codigo);}
   jdbc.update("insert into public.crm_contrato_anuncio values(?,?,'REFERENCIA') on conflict do nothing",contrato,ad);ref.put("anuncio_id",ad);
  }
  if(!ampliar)for(var p:lista(d,"prestaciones"))jdbc.update("insert into public.crm_trabajo_servicio(contrato_id,tipo,nombre,descripcion,fecha,cantidad,prestacion) values(?,'ENTREGABLE',?,?,?,?,?)",contrato,p.get("prestacion"),"Compromiso acordado al crear el contrato",fecha(d,"hasta"),entero(p,"cantidad",1,10000),p.get("prestacion"));
  Map<String,Object> combinado=new LinkedHashMap<>(anterior);combinado.putAll(d);if(ampliar)for(String k:List.of("piezas","referencias","documentos")){List<Map<String,Object>> elementos=new ArrayList<>(lista(anterior,k));elementos.addAll(lista(d,k));combinado.put(k,elementos);}combinado.remove("ampliar_contrato_id");
  jdbc.update("insert into public.crm_contrato_config values(?,?::jsonb,?) on conflict(contrato_id) do update set datos=excluded.datos",contrato,json.writeValueAsString(combinado),id);
  if(ampliar)jdbc.update("insert into public.crm_contrato_ampliacion(id,contrato_id,datos,autor_id) values(?,?,?::jsonb,?)",id,contrato,json.writeValueAsString(d),autor);
  jdbc.update("update public.crm_alta_contrato set contrato_id=?,version=version+1,updated_at=now() where id=?",contrato,id);evento(contrato,ampliar?"AGREGAR_ELEMENTOS":"CREAR_DESDE_ASISTENTE",autor);return Map.of("id",contrato);
 }
 public Map<String,Object> detalle(long id,UUID u){leer(u);var filas=jdbc.queryForList("select * from public.crm_acuerdo where id=? and tipo='CONTRATO'",id);if(filas.isEmpty())return error404();var contrato=filas.getFirst();var configs=jdbc.queryForList("select datos from public.crm_contrato_config where contrato_id=?",id);return Map.of("contrato",contrato,"configuracion",configs.isEmpty()?Map.of():mapa(configs.getFirst().get("datos")),"prestaciones",alcance.listar(id),"anuncios",jdbc.queryForList("select distinct a.*,p.plataforma,p.moneda,v.origen,min(m.fecha) metricas_desde,max(m.fecha) metricas_hasta,count(m.fecha) metricas_filas from public.crm_anuncio a join public.crm_cuenta_publicitaria p on p.id=a.cuenta_id left join public.crm_contrato_anuncio v on v.anuncio_id=a.id and v.contrato_id=? left join public.crm_anuncio_metrica m on m.anuncio_id=a.id where a.contrato_id=? or v.contrato_id=? group by a.id,p.id,v.origen order by a.id",id,id,id),"contenidos",jdbc.queryForList("select c.* from public.crm_contenido c join public.crm_acuerdo_campana v on v.campana_id=c.campana_id where v.contrato_id=?",id),"historial",jdbc.queryForList("select * from (select 'contexto-'||e.id id,e.accion,e.created_at,u.nombres autor from public.crm_contrato_evento e join public.usuario u on u.id_usuario=e.autor_id where e.contrato_id=? union all select 'operacion-'||a.id,a.accion,a.created_at,u.nombres from public.crm_auditoria a left join public.usuario u on u.id_usuario=a.autor_id where (a.recurso='agencia_contratos' and a.registro_id=?) or (a.recurso='agencia_anuncios' and exists(select 1 from public.crm_anuncio ad where ad.id=a.registro_id and (ad.contrato_id=? or exists(select 1 from public.crm_contrato_anuncio v where v.anuncio_id=ad.id and v.contrato_id=?)))) or (a.recurso in ('agencia_entregables','agencia_informes','agencia_recomendaciones','agencia_ajustes') and exists(select 1 from public.crm_trabajo_servicio t where t.id=a.registro_id and t.contrato_id=?))) h order by created_at desc limit 100",id,id,id,id,id));}
 public void activar(long id){var f=jdbc.queryForList("select datos from public.crm_contrato_config where contrato_id=?",id);if(f.isEmpty())return;var d=mapa(f.getFirst().get("datos"));if(!d.get("servicio").equals("ANALISIS")&&lista(d,"piezas").isEmpty())throw invalido("Faltan materiales o producción pendiente");if(!d.get("servicio").equals("DIFUSION")&&lista(d,"referencias").isEmpty())throw invalido("Faltan anuncios para analizar");}
 private void evento(long id,String accion,long autor){jdbc.update("insert into public.crm_contrato_evento(contrato_id,accion,autor_id) values(?,?,?)",id,accion,autor);}
 private ExcepcionApi conflicto(){return new ExcepcionApi(HttpStatus.CONFLICT,"CRM_CONCURRENCIA","El borrador cambió. Reabre la última versión antes de guardar");}
